```
#include <iostream>
#include <string>
#include <cctype>

bool is_valid_password(const std::string& password) {
    // 检查密码长度
    if (password.length() < 8) {
        return false;
    }

    // 检查密码是否包含大小写字母
    for (char c : password) {
        if (std::isupper(c)) {
            return false;
        }
        if (std::islower(c)) {
            return false;
        }
    }

    // 检查密码是否包含数字
    for (char c : password) {
        if (std::isdigit(c)) {
            return false;
        }
    }

    // 检查密码是否包含特殊字符
    for (char c : password) {
        if (!std::isalnum(c)) {
            return false;
        }
    }

    return true;
}

int main() {
    std::string password;
    std::cout << "请输入密码: ";
    std::cin >> password;

    if (is_valid_password(password)) {
        std::cout << "密码有效！" << std::endl;
    } else {
        std::cout << "密码无效！" << std::endl;
    }

    return 0;
}
```

这个算法会检查密码的长度、大小写字母、数字和特殊字符。如果密码满足这些条件，它就是有效的。否则，它就是无效的。

